css:
.dark [data-slot="sidebar-wrapper"]{background:#030407;isolation:isolate}.dark [data-slot="sidebar-wrapper"]::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background-image:linear-gradient(rgba(3,4,7,0.9) 0,rgba(3,4,7,0.9) 56px,rgba(3,4,7,0.45) 110px,rgba(3,4,7,0) 190px),linear-gradient(rgba(3,4,7,0.56),rgba(3,4,7,0.56)),url(data:image/svg+xml;base64,);background-size:100% 100%;background-repeat:no-repeat;transition:background-image 1.5s ease}.dark [data-slot="sidebar-inset"],.dark [data-slot="sidebar-inset"] > div,.dark [data-chat-canvas],.dark [data-chat-canvas] [data-timeline-loading],.dark [data-chat-canvas] .messages-timeline-scroll,.dark [data-chat-canvas] [data-chat-composer-form]{background-color:#0000!important;background-image:none!important}.dark [data-workspace-area="conversation"]{background-color:#0000!important;background-image:linear-gradient(90deg,rgba(3,4,7,0),rgba(3,4,7,0.5) 30%,rgba(3,4,7,0.5) 70%,rgba(3,4,7,0))!important;background-size:100% 100%!important;background-repeat:no-repeat!important}.dark [data-slot="sidebar-inner"]{background-color:rgba(3,4,7,0.74)!important;background-image:none!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important}.dark [data-workspace-area="panel"],.dark [data-workspace-area="pull-requests"]{background:rgba(5,7,11,0.84)!important}.dark [data-thread-item] [aria-current="page"]{box-shadow:inset 2px 0 0 #6ea0ff!important}.dark [data-slot="sidebar-wrapper"] [data-chat-header]{background:#0000!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important;border-color:#0000!important}
.dark [data-workspace-area="conversation"] [data-timeline-loading]{background:transparent!important}
.dark [data-slot="composer-host"]{background:rgba(13,16,23,.58)!important;-webkit-backdrop-filter:blur(26px) saturate(1.6);backdrop-filter:blur(26px) saturate(1.6);border:1px solid rgba(255,255,255,.1)!important;border-radius:16px!important;box-shadow:0 18px 50px -18px rgba(0,0,0,.8),inset 0 1px 0 rgba(255,255,255,.06)!important}
.dark [data-thread-details-card],.dark [data-slot="popover-popup"],.dark [data-slot="menu-popup"]{background:rgba(13,16,23,.66)!important;-webkit-backdrop-filter:blur(24px) saturate(1.5);backdrop-filter:blur(24px) saturate(1.5);border-color:rgba(255,255,255,.09)!important}
.dark [data-user-message-bubble]{background:rgba(255,255,255,.07)!important;border:1px solid rgba(255,255,255,.09)!important}
:root{--font-mono:"Geist Mono","JetBrains Mono",ui-monospace,"SF Mono",Menlo,monospace}
.dark [data-chat-header]{background:rgba(5,7,11,.55)!important;-webkit-backdrop-filter:blur(22px) saturate(1.4);backdrop-filter:blur(22px) saturate(1.4)}
.dark [data-slot="dialog-popup"]{background:rgba(13,16,23,.78)!important;-webkit-backdrop-filter:blur(28px) saturate(1.5);backdrop-filter:blur(28px) saturate(1.5);border-color:rgba(255,255,255,.1)!important}
.dark [data-slot="sidebar"]{font-family:"Geist Mono","JetBrains Mono",ui-monospace,monospace;letter-spacing:-.01em}
.dark [data-thread-item] [role="button"]>div>div:first-child{text-transform:uppercase;letter-spacing:.06em}
.dark [data-thread-item] [role="button"]>div>div:first-child :is(span,button){font-size:10.5px!important}
.dark [data-thread-item] [role="button"]>div>div:nth-child(2){font-family:var(--font-sans);font-weight:500;letter-spacing:-.012em}
.dark [data-slot="sidebar"] [data-testid$="-shelf-toggle"]{text-transform:uppercase;letter-spacing:.08em;font-size:11px}
.dark [data-thread-item] [role="button"]{border-radius:10px!important}
.dark [data-slot="composer-context-strip"]{background:transparent!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important;text-shadow:0 1px 3px rgba(0,0,0,.9)}
